window.GUIDE={"cats": {"sights": {"sec": "see", "title": "Sights & oddities", "emoji": "🏰", "color": "#C0392B"}, "galleries": {"sec": "see", "title": "Galleries", "emoji": "🎨", "color": "#8E44C9"}, "shops": {"sec": "see", "title": "Indie shops & makers", "emoji": "🛍️", "color": "#E8930C"}, "records": {"sec": "see", "title": "Records, books & comics", "emoji": "📀", "color": "#1877D0"}, "vintage": {"sec": "see", "title": "Vintage & antiques", "emoji": "🧥", "color": "#0F766E"}, "gear": {"sec": "see", "title": "Cameras, music & tech", "emoji": "📷", "color": "#0E7490"}, "food": {"sec": "see", "title": "Food shops & world grocers", "emoji": "🧀", "color": "#B45309"}, "fun": {"sec": "see", "title": "Escape rooms & things to do", "emoji": "🧩", "color": "#DB2777"}, "parks": {"sec": "see", "title": "Parks & walks", "emoji": "🌳", "color": "#2F855A"}, "trips": {"sec": "see", "title": "Day trips", "emoji": "🚗", "color": "#1D4ED8"}, "cafes": {"sec": "eat", "title": "Cafés & coffee", "emoji": "☕", "color": "#0F9D8A"}, "cheap": {"sec": "eat", "title": "Cheap eats & street food", "emoji": "🌮", "color": "#E8483B"}, "mid": {"sec": "eat", "title": "Mid-range", "emoji": "🍽️", "color": "#E8930C"}, "splurge": {"sec": "eat", "title": "Splurge & Michelin", "emoji": "⭐", "color": "#8E44C9"}, "pubs": {"sec": "eat", "title": "Historic & real-ale pubs", "emoji": "🍺", "color": "#A0522D"}, "bars": {"sec": "eat", "title": "Cocktails & craft bars", "emoji": "🍸", "color": "#1877D0"}, "music": {"sec": "eat", "title": "Live music & comedy", "emoji": "🎸", "color": "#7C3AED"}}, "items": [{"id": "n1", "cat": "sights", "name": "City of Caves", "addr": "Upper Level, Broadmarsh, NG1 7LS", "text": "Nottingham sits on soft sandstone riddled with more than 800 man-made caves. This guided tour takes you through medieval tannery pits, a WWII air-raid shelter and Victorian slum cellars right under the city centre. Tours run about every 30–45 minutes and take around an hour.", "tip": "Book a timed slot online at weekends", "lat": 52.950294, "lon": -1.146042, "price": 0, "walk": 7, "img": "img/n1.svg", "q": "City of Caves, Broadmarsh, NG1 7LS, Nottingham", "ta": true, "far": false, "web": "https://www.cityofcaves.com", "drive": ""}, {"id": "n2", "cat": "sights", "name": "National Justice Museum", "addr": "Shire Hall, High Pavement, NG1 1HN", "text": "A Victorian courthouse and county gaol in the Lace Market, where you can stand in the dock, see the cells and the execution yard, and hear the grim stories of people tried here. Actors in costume bring the courtroom to life on some days.", "tip": "Allow 2 hours; good on a rainy day", "lat": 52.95071, "lon": -1.144218, "price": 0, "walk": 8, "img": "img/n2.svg", "q": "National Justice Museum, Shire Hall, High Pavement, NG1 1HN, Nottingham", "ta": true, "far": false, "web": "https://www.nationaljusticemuseum.org.uk", "drive": ""}, {"id": "n3", "cat": "sights", "name": "Nottingham Castle", "addr": "Lenton Road, NG1 6EL", "text": "Not a medieval castle but a 17th-century ducal mansion on top of Castle Rock, rebuilt after rioters burned it in 1831. Inside: the city's art collection, lace galleries and the Robin Hood story; underneath, Mortimer's Hole and other caves. Free grounds views over the city.", "tip": "Check opening and cave tour times before you go", "lat": 52.9495, "lon": -1.15468, "price": 0, "walk": 9, "img": "img/n3.svg", "q": "Nottingham Castle, Lenton Road, NG1 6EL, Nottingham", "ta": true, "far": false, "web": "https://www.nottinghamcastle.org.uk", "drive": ""}, {"id": "n4", "cat": "sights", "name": "Park Tunnel", "addr": "Derby Road entrance by Canning Circus, NG7 1", "text": "A tunnel cut through the sandstone in 1855 as a carriage entrance to The Park, the private Victorian estate of grand villas below the Castle. It was never used for carriages because the slope was too steep. Now a free, atmospheric footpath with an open-air light well in the middle.", "tip": "Walk down from Derby Road into The Park", "lat": 52.954165, "lon": -1.159836, "price": 0, "walk": 11, "img": "img/n4.svg", "q": "Park Tunnel, Derby Road entrance by Canning Circus, NG7 1, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n5", "cat": "sights", "name": "Old Market Square & the Council House", "addr": "Old Market Square, NG1 2DT", "text": "The UK's second-largest civic square, overlooked by the 1929 Council House with its dome and two stone lions. 'Meet you by the left lion' is the classic local rendezvous, and gave the city's culture magazine its name. The Exchange Arcade inside the Council House has a painted dome.", "tip": "Christmas market and ice rink here every winter", "lat": 52.953424, "lon": -1.148611, "price": 0, "walk": 1, "img": "img/n5.svg", "q": "Old Market Square & the Council House, Old Market Square, NG1 2DT, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n6", "cat": "sights", "name": "Lace Market & St Mary's Church", "addr": "High Pavement, NG1 1HF", "text": "The medieval heart of Nottingham, rebuilt in the 1800s as a canyon of tall red-brick lace warehouses and showrooms. St Mary's is the city's oldest church, a 15th-century Perpendicular giant with fine stained glass. The Adams Building on Stoney Street was built with a chapel and library for its workers.", "tip": "Wander Stoney St, Broadway and St Mary's Gate", "lat": 52.951187, "lon": -1.143048, "price": 0, "walk": 8, "img": "img/n6.svg", "q": "Lace Market & St Mary's Church, High Pavement, NG1 1HF, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n7", "cat": "sights", "name": "Robin Hood statue", "addr": "Castle Road, NG1 6AA", "text": "The bronze outlaw by James Woodford, unveiled in 1952 below the Castle walls. His arrow has been stolen so many times it's a running joke. Every visitor gets the photo.", "tip": "Quick photo stop on the way to the Trip", "lat": 52.9506, "lon": -1.152, "price": 0, "walk": 5, "img": "img/n7.svg", "q": "Robin Hood statue, Castle Road, NG1 6AA, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n8", "cat": "sights", "name": "Green's Windmill", "addr": "Windmill Lane, Sneinton, NG2 4QB", "text": "A working tower windmill in Sneinton, once owned by the mathematician George Green, whose work underpins modern physics. You can buy stoneground flour milled on site and learn about Green in the small science centre.", "tip": "Open limited days; check before you go", "lat": 52.952098, "lon": -1.129386, "price": 0, "walk": 22, "img": "img/n8.svg", "q": "Green's Windmill, Windmill Lane, Sneinton, NG2 4QB, Nottingham", "ta": true, "far": false, "web": "https://www.greensmill.org.uk", "drive": ""}, {"id": "n9", "cat": "sights", "name": "The Arboretum", "addr": "Waverley Street, NG7 4HF", "text": "Nottingham's first public park, opened in 1852: a hilly Victorian garden with a pagoda, bandstand, aviary and Crimean War cannons. Quiet, free and a short walk north of the centre.", "tip": "Pair with Mansfield Road pubs", "lat": 52.959801, "lon": -1.157383, "price": 0, "walk": 14, "img": "img/n9.svg", "q": "The Arboretum, Waverley Street, NG7 4HF, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n10", "cat": "sights", "name": "Theatre Royal & Royal Concert Hall", "addr": "Theatre Square, NG1 5ND", "text": "The 1865 Theatre Royal with its six Corinthian columns, joined to the modern Royal Concert Hall. Touring West End shows, panto, comedy and big concerts. Even if you're not going in, the portico lit at night is one of the city's best sights.", "tip": "Panto season runs through December", "lat": 52.955697, "lon": -1.151785, "price": 0, "walk": 5, "img": "img/n10.svg", "q": "Theatre Royal & Royal Concert Hall, Theatre Square, NG1 5ND, Nottingham", "ta": true, "far": false, "web": "https://trch.co.uk", "drive": ""}, {"id": "n11", "cat": "sights", "name": "Broadway Cinema", "addr": "14–18 Broad Street, NG1 3AL", "text": "The city's independent cinema in a former Methodist chapel in Hockley, showing art-house, world and classic film. Its café-bar is open to everyone and is one of Hockley's best meeting spots. A room here was designed by Paul Smith.", "tip": "Drop in for a drink even without a ticket", "lat": 52.954306, "lon": -1.143663, "price": 0, "walk": 7, "img": "img/n11.svg", "q": "Broadway Cinema, 14–18 Broad Street, NG1 3AL, Nottingham", "ta": true, "far": false, "web": "https://www.broadway.org.uk", "drive": ""}, {"id": "n12", "cat": "sights", "name": "Wollaton Hall & Deer Park", "addr": "Wollaton Park, NG8 2AE", "text": "A spectacular Elizabethan prodigy house, built in the 1580s, set in a 500-acre park with free-roaming red and fallow deer. It was Wayne Manor in The Dark Knight Rises. The natural history museum inside is free; parking is paid.", "tip": "Drive or bus 30; allow half a day", "lat": 52.94796, "lon": -1.209771, "price": 0, "walk": 66, "img": "img/n12.svg", "q": "Wollaton Hall & Deer Park, Wollaton Park, NG8 2AE, Nottingham", "ta": true, "far": true, "web": "", "drive": ""}, {"id": "n13", "cat": "galleries", "name": "Nottingham Contemporary", "addr": "Weekday Cross, NG1 2GB", "text": "One of the UK's largest contemporary art centres, in a building wrapped in concrete panels cast from a Victorian lace pattern. Four free galleries, a strong bookshop and a café, right on the edge of the Lace Market. 2026 includes the first institutional solo show of the late British artist Sarah Cunningham.", "tip": "Free · closed Mondays", "lat": 52.951048, "lon": -1.145929, "price": 0, "walk": 6, "img": "img/n13.svg", "q": "Nottingham Contemporary, Weekday Cross, NG1 2GB, Nottingham", "ta": true, "far": false, "web": "https://www.nottinghamcontemporary.org", "drive": ""}, {"id": "n14", "cat": "galleries", "name": "Surface Gallery", "addr": "16 Southwell Road, NG1 1DL", "text": "A volunteer-led, artist-run contemporary gallery run as a co-operative by early-career artists. Ambitious, rough-edged shows, open calls and an annual street art festival.", "tip": "Opens around exhibitions; check dates", "lat": 52.953293, "lon": -1.137724, "price": 0, "walk": 13, "img": "img/n14.svg", "q": "Surface Gallery, 16 Southwell Road, NG1 1DL, Nottingham", "ta": false, "far": false, "web": "https://www.surfacegallery.org", "drive": ""}, {"id": "n15", "cat": "galleries", "name": "BACKLIT", "addr": "Alfred House, Ashley Street, NG3 1JG", "text": "An independent artist-led space founded in 2008, with galleries across three floors of an 1872 Victorian building in Sneinton, plus studios. A new ground-floor gallery and People's Archive opened through 2026. Its 'Our Marian' sculpture now stands at Tollhouse Hill.", "tip": "Open during exhibitions; check online", "lat": 52.95568, "lon": -1.13568, "price": 0, "walk": 16, "img": "img/n15.svg", "q": "BACKLIT, Alfred House, Ashley Street, NG3 1JG, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n16", "cat": "galleries", "name": "New Art Exchange", "addr": "39–41 Gregory Boulevard, Hyson Green, NG7 6BE", "text": "The UK's largest gallery dedicated to culturally diverse contemporary art, in the heart of Hyson Green. Free exhibitions, a café, and Radford Road's food shops on the doorstep.", "tip": "Tram to Hyson Green Market", "lat": 52.96595, "lon": -1.168443, "price": 0, "walk": 31, "img": "img/n16.svg", "q": "New Art Exchange, 39–41 Gregory Boulevard, Hyson Green, NG7 6BE, Nottingham", "ta": true, "far": true, "web": "https://www.nae.org.uk", "drive": ""}, {"id": "n17", "cat": "galleries", "name": "Primary", "addr": "33 Seely Road, Lenton, NG7 1NU", "text": "A former Victorian primary school, now artists' studios with a public programme of exhibitions, talks and events. A real look inside the city's artist community.", "tip": "Best on open days and event nights", "lat": 52.95531, "lon": -1.1677, "price": 0, "walk": 20, "img": "img/n17.svg", "q": "Primary, 33 Seely Road, Lenton, NG7 1NU, Nottingham", "ta": false, "far": false, "web": "https://www.weareprimary.org", "drive": ""}, {"id": "n18", "cat": "galleries", "name": "Bonington Gallery", "addr": "Bonington Building, Dryden Street, NG1 4FZ", "text": "Nottingham Trent University's free gallery in its brutalist art-school building. Thoughtful, often experimental contemporary exhibitions and rarely crowded.", "tip": "Term-time programme", "lat": 52.95827, "lon": -1.15321, "price": 0, "walk": 10, "img": "img/n18.svg", "q": "Bonington Gallery, Bonington Building, Dryden Street, NG1 4FZ, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n19", "cat": "galleries", "name": "Fletcher Gate Fine Art Gallery", "addr": "18 Fletcher Gate, Lace Market, NG1 2FZ", "text": "Also known as the Fletcher Gate Art Gallery. An independent gallery for original fine art for sale, from local and national artists, in the Lace Market. A relaxed place to browse paintings you could actually take home.", "tip": "Thu–Sun 11:00–16:00", "lat": 52.953, "lon": -1.1458, "price": 0, "walk": 4, "img": "img/n19.svg", "q": "Fletcher Gate Fine Art Gallery, 18 Fletcher Gate, Lace Market, NG1 2FZ, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n20", "cat": "galleries", "name": "Nottingham Society of Artists", "addr": "61 Friar Lane, NG1 6DA", "text": "Founded in 1880, the society runs its own gallery behind an unassuming door on Friar Lane. Rolling exhibitions of members' work, often very affordable.", "tip": "Combine with the Castle", "lat": 52.951389, "lon": -1.152897, "price": 0, "walk": 5, "img": "img/n20.svg", "q": "Nottingham Society of Artists, 61 Friar Lane, NG1 6DA, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n21", "cat": "galleries", "name": "Djanogly Gallery, Lakeside Arts", "addr": "University Park, NG7 2RD", "text": "The University of Nottingham's arts centre beside the Highfields lake, with a gallery of historic and modern shows, plus theatre and music. A lovely place for a lakeside walk.", "tip": "Tram to University of Nottingham", "lat": 52.9393, "lon": -1.1886, "price": 0, "walk": 49, "img": "img/n21.svg", "q": "Djanogly Gallery, Lakeside Arts, University Park, NG7 2RD, Nottingham", "ta": true, "far": true, "web": "https://www.lakesidearts.org.uk", "drive": ""}, {"id": "n22", "cat": "galleries", "name": "Hooten Street Project", "addr": "Sneinton, NG3", "text": "A tiny space converted from part of an artist's studio, showing print and wall-based work by invited artists. Very small and occasional, which is the charm.", "tip": "Check dates before you go", "lat": 52.9552, "lon": -1.137, "price": 0, "walk": 14, "img": "img/n22.svg", "q": "Hooten Street Project, Sneinton, NG3, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n23", "cat": "galleries", "name": "Debbie Bryan", "addr": "1st floor, 4–6 St Peter's Gate, NG1 2JG", "text": "An award-winning independent creative gallery, shop and tearoom run by a textile designer. Nottingham lace, local makers, prints and gifts, plus craft workshops you can book.", "tip": "Book a workshop for a creative afternoon", "lat": 52.95215, "lon": -1.1479, "price": 0, "walk": 3, "img": "img/n23.svg", "q": "Debbie Bryan, 1st floor, 4–6 St Peter's Gate, NG1 2JG, Nottingham", "ta": true, "far": false, "web": "https://www.debbiebryan.co.uk", "drive": ""}, {"id": "n24", "cat": "shops", "name": "Sneinton Market Avenues", "addr": "Avenue A–C, Sneinton Market, NG1 1DW", "text": "Rows of old wholesale-market units converted into tiny shops and studios for designers, makers, florists and creative businesses, with Bustler street food in the middle. The heart of the Creative Quarter's east side.", "tip": "Saturdays are best · market hall refurbishment from autumn 2026", "lat": 52.95474, "lon": -1.13791, "price": 0, "walk": 13, "img": "img/n24.svg", "q": "Sneinton Market Avenues, Sneinton Market, NG1 1DW, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n25", "cat": "shops", "name": "Cobden Chambers", "addr": "off Pelham Street, NG1 2ED", "text": "A hidden courtyard off Pelham Street, home to small independent shops, makers and cafés. Easy to walk straight past the entrance.", "tip": "Tenants change; peek in whenever you pass", "lat": 52.953902, "lon": -1.145813, "price": 0, "walk": 4, "img": "img/n25.svg", "q": "Cobden Chambers, Pelham Street, NG1 2ED, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n26", "cat": "shops", "name": "Hurts Yard", "addr": "Hurts Yard, NG1 6JD", "text": "A narrow Victorian alley between Upper Parliament Street and Long Row packed with independents: records, barbers, vintage, and newer food spots like Shio at Six Richmond House.", "tip": "Start at the Upper Parliament St end", "lat": 52.954279, "lon": -1.152431, "price": 0, "walk": 3, "img": "img/n26.svg", "q": "Hurts Yard, Hurts Yard, NG1 6JD, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n27", "cat": "shops", "name": "Flying Horse Walk", "addr": "Poultry, NG1 2HN", "text": "A shopping passage through a former 17th-century coaching inn, with timbered gables over the entrance. Small shops, 200 Degrees coffee and Bar Gigi.", "tip": "Good start to a shopping loop", "lat": 52.952802, "lon": -1.148582, "price": 0, "walk": 2, "img": "img/n27.svg", "q": "Flying Horse Walk, Poultry, NG1 2HN, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n28", "cat": "shops", "name": "Bridlesmith Gate & Bridlesmith Walk", "addr": "Bridlesmith Gate, NG1 2GR", "text": "Nottingham's old fashion street, still lined with independent boutiques alongside designer names, plus the tucked-away Bridlesmith Walk lane of small units.", "tip": "Walk it towards Hockley", "lat": 52.952122, "lon": -1.147159, "price": 0, "walk": 4, "img": "img/n28.svg", "q": "Bridlesmith Gate & Bridlesmith Walk, Bridlesmith Gate, NG1 2GR, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n29", "cat": "shops", "name": "West End Arcade", "addr": "Upper Parliament Street, NG1 6JR", "text": "A small arcade off Upper Parliament Street with independent fashion, gifts and cafés, near Hurts Yard and the Theatre Royal.", "tip": "Combine with Hurts Yard", "lat": 52.954322, "lon": -1.153294, "price": 0, "walk": 4, "img": "img/n29.svg", "q": "West End Arcade, Upper Parliament Street, NG1 6JR, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n30", "cat": "shops", "name": "Paul Smith, Willoughby House", "addr": "20 Low Pavement, NG1 7DL", "text": "Sir Paul Smith is Nottingham born and opened his first tiny shop here in 1970. His flagship is a gorgeous Georgian townhouse on Low Pavement, worth seeing for the interiors and the eccentric displays.", "tip": "Look out for the quirky objects in the windows", "lat": 52.951322, "lon": -1.147393, "price": 0, "walk": 4, "img": "img/n30.svg", "q": "Paul Smith, Willoughby House, 20 Low Pavement, NG1 7DL, Nottingham", "ta": true, "far": false, "web": "https://www.paulsmith.com", "drive": ""}, {"id": "n31", "cat": "shops", "name": "Delilah Fine Foods", "addr": "12 Victoria Street, NG1 2EX", "text": "A deli in a grand old banking hall: marble counters, a mezzanine café and a huge cheese counter. Buy Nottinghamshire Stilton, charcuterie and wine to take home in the car.", "tip": "Ask for Colston Bassett Stilton, made in Notts", "lat": 52.95312, "lon": -1.14644, "price": 0, "walk": 4, "img": "img/n31.svg", "q": "Delilah Fine Foods, 12 Victoria Street, NG1 2EX, Nottingham", "ta": true, "far": false, "web": "https://www.delilahfinefoods.co.uk", "drive": ""}, {"id": "n32", "cat": "shops", "name": "Victoria Centre Market", "addr": "Victoria Centre (upper level), NG1 3QN", "text": "An old-school indoor market above the shopping centre: fishmongers, butchers, bric-a-brac, sewing supplies and cafés. Downstairs, don't miss Rowland Emett's whimsical water clock.", "tip": "Emett clock performs on the hour", "lat": 52.956382, "lon": -1.146493, "price": 0, "walk": 7, "img": "img/n32.svg", "q": "Victoria Centre Market, Victoria Centre (upper level), NG1 3QN, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n33", "cat": "records", "name": "Rough Trade Nottingham", "addr": "5 Broad Street, Hockley, NG1 3AJ", "text": "Two floors of new vinyl, books and zines, plus a café-bar and a small venue for in-store gigs. The anchor of Hockley's music scene.", "tip": "In-store sets are often free; check events", "lat": 52.953898, "lon": -1.144173, "price": 0, "walk": 6, "img": "img/n33.svg", "q": "Rough Trade Nottingham, 5 Broad Street, Hockley, NG1 3AJ, Nottingham", "ta": true, "far": false, "web": "https://www.roughtrade.com", "drive": ""}, {"id": "n34", "cat": "records", "name": "Rob's Records", "addr": "4–5 Hurts Yard, NG1 6JD", "text": "A crate-digger's institution: crammed racks of second-hand vinyl across every genre, in the Hurts Yard alley.", "tip": "Check @robsrecordsnottingham for hours", "lat": 52.9548, "lon": -1.1516, "price": 0, "walk": 3, "img": "img/n34.svg", "q": "Rob's Records, 4–5 Hurts Yard, NG1 6JD, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n35", "cat": "records", "name": "Five Leaves Bookshop", "addr": "14a Long Row, NG1 2DH", "text": "A radical, independent bookshop and publisher up a passage off Long Row. Strong on politics, poetry, local history, LGBTQ+ and small-press fiction, with regular author events.", "tip": "Their Nottingham history titles make great gifts", "lat": 52.954104, "lon": -1.148793, "price": 0, "walk": 2, "img": "img/n35.svg", "q": "Five Leaves Bookshop, 14a Long Row, NG1 2DH, Nottingham", "ta": true, "far": false, "web": "https://fiveleavesbookshop.co.uk", "drive": ""}, {"id": "n36", "cat": "records", "name": "Page 45", "addr": "9 Market Street, NG1 6HY", "text": "An award-winning comics and graphic novel shop, with handwritten staff reviews on half the shelves. Brilliant for beginners: tell them what novels you like and let them pick.", "tip": "Ask for a recommendation", "lat": 52.954121, "lon": -1.151488, "price": 0, "walk": 2, "img": "img/n36.svg", "q": "Page 45, 9 Market Street, NG1 6HY, Nottingham", "ta": true, "far": false, "web": "https://www.page45.com", "drive": ""}, {"id": "n37", "cat": "vintage", "name": "Hopkinsons Vintage & Antiques", "addr": "21 Station Street, NG2 3AJ", "text": "A huge multi-dealer vintage, antique and retro emporium in a former warehouse opposite the railway station. Furniture, homewares, clothes, militaria and odd curios over several floors.", "tip": "Allow at least an hour", "lat": 52.94782, "lon": -1.14614, "price": 0, "walk": 11, "img": "img/n37.svg", "q": "Hopkinsons Vintage & Antiques, 21 Station Street, NG2 3AJ, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n38", "cat": "vintage", "name": "Derby Road antiques & vintage strip", "addr": "Derby Road, NG1 5", "text": "The slope from the centre up to Canning Circus is lined with antique dealers, vintage furniture, guitar shops and odd specialists. A slow browse that ends at three good pubs.", "tip": "Walk up, lunch at the top, stroll down", "lat": 52.9545, "lon": -1.159, "price": 0, "walk": 10, "img": "img/n38.svg", "q": "Derby Road antiques & vintage strip, Derby Road, NG1 5, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n39", "cat": "vintage", "name": "Cow Vintage", "addr": "3 Carlton Street, Hockley, NG1 1NL", "text": "A big vintage clothing store listed among the city's go-to second-hand fashion shops, with racks of denim, sportswear and retro jackets.", "tip": "Several Hockley vintage shops have closed recently; check it's trading", "lat": 52.95363, "lon": -1.14499, "price": 0, "walk": 5, "img": "img/n39.svg", "q": "Cow Vintage, 3 Carlton Street, Hockley, NG1 1NL, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n40", "cat": "vintage", "name": "Goose Gate vintage & Hockley shops", "addr": "Goose Gate, Hockley, NG1 1FF", "text": "Goose Gate and Carlton Street are Hockley's main browsing streets: vintage clothes, skate and streetwear, plants, tattoo parlours and bars. Jesse Boot opened his first shop at 16 Goose Gate; look up for the original ironwork.", "tip": "Best late morning before the bars fill", "lat": 52.953652, "lon": -1.143536, "price": 0, "walk": 7, "img": "img/n40.svg", "q": "Goose Gate vintage & Hockley shops, Goose Gate, Hockley, NG1 1FF, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n41", "cat": "cafes", "name": "200 Degrees, Flying Horse Walk", "addr": "Flying Horse Walk, NG1 2HN", "text": "The Nottingham-born roaster that went national. This branch sits in the old coaching-inn arcade, and beans are roasted in the city.", "tip": "Buy a bag of beans to take home", "lat": 52.953065, "lon": -1.148737, "price": 1, "walk": 1, "img": "img/n41.svg", "q": "200 Degrees, Flying Horse Walk, Flying Horse Walk, NG1 2HN, Nottingham", "ta": true, "far": false, "web": "https://200degs.com", "drive": ""}, {"id": "n42", "cat": "cafes", "name": "Doughnotts", "addr": "Exchange Arcade, NG1 2DD", "text": "Nottingham's own doughnut company, started here in 2015, with its city café in the Council House's Exchange Arcade. Big, inventive, sourdough doughnuts with vegan options.", "tip": "Closed Mondays · get there before they sell out", "lat": 52.95328, "lon": -1.14778, "price": 1, "walk": 2, "img": "img/n42.svg", "q": "Doughnotts, Exchange Arcade, NG1 2DD, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n43", "cat": "cafes", "name": "The Pudding Pantry", "addr": "Trinity Square, NG1 4AF", "text": "Over-the-top pancake stacks, brunches and cakes. Exactly what it sounds like, and very popular.", "tip": "Weekend queues from 10am", "lat": 52.95652, "lon": -1.149077, "price": 2, "walk": 6, "img": "img/n43.svg", "q": "The Pudding Pantry, Trinity Square, NG1 4AF, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n44", "cat": "cafes", "name": "Debbie Bryan tearoom", "addr": "1st floor, 4–6 St Peter's Gate, NG1 2JG", "text": "Tea, cake and light lunches among the makers' displays at Debbie Bryan's creative shop.", "tip": "Combine with a craft workshop", "lat": 52.95215, "lon": -1.1479, "price": 1, "walk": 3, "img": "img/n44.svg", "q": "Debbie Bryan tearoom, 1st floor, 4–6 St Peter's Gate, NG1 2JG, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n45", "cat": "cafes", "name": "Malt Cross", "addr": "16 St James's Street, NG1 6FG", "text": "A rare surviving 1877 Victorian music hall, with a glass barrel-vaulted roof and iron balconies, now a charity-run café-bar. Coffee by day, drinks and music at night, and caves below with a small exhibition space.", "tip": "Ask if the caves are open to wander", "lat": 52.95307, "lon": -1.152407, "price": 1, "walk": 3, "img": "img/n45.svg", "q": "Malt Cross, 16 St James's Street, NG1 6FG, Nottingham", "ta": true, "far": false, "web": "https://www.maltcross.com", "drive": ""}, {"id": "n46", "cat": "cheap", "name": "Bustler Market", "addr": "Sneinton Market Avenues, NG1 1DW", "text": "A big street-food hall with permanent traders, bars and 500+ seats in Sneinton Market. Something for everyone and very sociable.", "tip": "Busiest and best Fri–Sat evenings", "lat": 52.954286, "lon": -1.137591, "price": 1, "walk": 13, "img": "img/n46.svg", "q": "Bustler Market, Sneinton Market Avenues, NG1 1DW, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n47", "cat": "cheap", "name": "Annie's Burger Shack", "addr": "5 Broadway, Lace Market, NG1 1PR", "text": "Enormous menu of American burgers, many with vegan versions, plus a great craft-beer fridge. A Lace Market institution.", "tip": "Check it's open: listings conflict", "lat": 52.9527, "lon": -1.1444, "price": 2, "walk": 6, "img": "img/n47.svg", "q": "Annie's Burger Shack, 5 Broadway, Lace Market, NG1 1PR, Nottingham", "ta": true, "far": false, "web": "https://www.anniesburgershack.com", "drive": ""}, {"id": "n48", "cat": "cheap", "name": "Shanghai Shanghai", "addr": "15 Goose Gate, Hockley, NG1 1FE", "text": "Proper numbing Sichuan cooking in a no-frills Hockley dining room. A local favourite for years.", "tip": "Share in a group; order the dry-fried green beans", "lat": 52.95375, "lon": -1.14312, "price": 2, "walk": 7, "img": "img/n48.svg", "q": "Shanghai Shanghai, 15 Goose Gate, Hockley, NG1 1FE, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n49", "cat": "cheap", "name": "Kayal", "addr": "8 Broad Street, Hockley, NG1 3AL", "text": "South Indian cooking from Kerala: dosas, coconut curries and seafood. A refreshing change from the standard curry house.", "tip": "The lunchtime thali is excellent value", "lat": 52.953869, "lon": -1.143772, "price": 2, "walk": 7, "img": "img/n49.svg", "q": "Kayal, 8 Broad Street, Hockley, NG1 3AL, Nottingham", "ta": true, "far": false, "web": "https://www.kayalrestaurant.com", "drive": ""}, {"id": "n50", "cat": "mid", "name": "Kushi-ya", "addr": "Enfield Chambers, 14a Low Pavement, NG1 7DL", "text": "A small, buzzy izakaya that moved in 2024 to Enfield Chambers, reached through a gated alleyway off Low Pavement. Charcoal-grilled skewers, Japanese small plates, and strong sake and natural wine lists.", "tip": "Sit at the counter to watch the grill", "lat": 52.95124, "lon": -1.14772, "price": 3, "walk": 4, "img": "img/n50.svg", "q": "Kushi-ya, Enfield Chambers, 14a Low Pavement, NG1 7DL, Nottingham", "ta": true, "far": false, "web": "https://www.kushi-ya.co.uk", "drive": ""}, {"id": "n51", "cat": "mid", "name": "Ibérico World Tapas", "addr": "The Shire Hall, High Pavement, NG1 1HN", "text": "Tapas in the vaulted, tiled basement of the old Shire Hall, candlelit and romantic. Spanish classics with detours to Asia and South America.", "tip": "The set lunch is great value", "lat": 52.95084, "lon": -1.14443, "price": 3, "walk": 7, "img": "img/n51.svg", "q": "Ibérico World Tapas, The Shire Hall, High Pavement, NG1 1HN, Nottingham", "ta": true, "far": false, "web": "https://www.ibericotapas.com", "drive": ""}, {"id": "n52", "cat": "mid", "name": "Bar Gigi", "addr": "Flying Horse Walk, NG1 2HN", "text": "A small Italian bar and kitchen in the Flying Horse Walk arcade, five years old in 2026. Aperitivo, pasta and a famously good burger.", "tip": "Casual lunch between shops", "lat": 52.953072, "lon": -1.148549, "price": 2, "walk": 1, "img": "img/n52.svg", "q": "Bar Gigi, Flying Horse Walk, NG1 2HN, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n53", "cat": "mid", "name": "Sexy Mamma Love Spaghetti", "addr": "3 Heathcoat Street, Hockley, NG1 3AA", "text": "The name's a joke but the pasta isn't. A tiny, cosy, family-run trattoria in Hockley with fresh pasta.", "tip": "Tiny room; book even midweek", "lat": 52.953822, "lon": -1.143596, "price": 2, "walk": 7, "img": "img/n53.svg", "q": "Sexy Mamma Love Spaghetti, 3 Heathcoat Street, Hockley, NG1 3AA, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n54", "cat": "mid", "name": "Shio", "addr": "Six Richmond House, Hurts Yard, NG1 6JD", "text": "One of 2026's notable new openings, in the Hurts Yard alley of independents.", "tip": "New places change fast; check menu and hours", "lat": 52.9545, "lon": -1.15254, "price": 2, "walk": 4, "img": "img/n54.svg", "q": "Shio, Six Richmond House, Hurts Yard, NG1 6JD, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n55", "cat": "mid", "name": "Café Roya", "addr": "130 Wollaton Road, Beeston, NG9 2PE", "text": "A much-loved vegetarian and vegan restaurant in Beeston with Persian-influenced cooking. Worth the tram ride.", "tip": "Small and mostly evenings; book", "lat": 52.930074, "lon": -1.218917, "price": 2, "walk": 86, "img": "img/n55.svg", "q": "Café Roya, 130 Wollaton Road, Beeston, NG9 2PE, Nottingham", "ta": true, "far": true, "web": "", "drive": ""}, {"id": "n56", "cat": "splurge", "name": "Alchemilla", "addr": "192 Derby Road, NG7 1NF", "text": "Alex Bond's Michelin-starred restaurant, built into a long-derelict Victorian coach house with a living roof. Inventive, vegetable-led tasting menus.", "tip": "Book weeks ahead · 15-min walk up Derby Road", "lat": 52.955033, "lon": -1.165557, "price": 4, "walk": 17, "img": "img/n56.svg", "q": "Alchemilla, 192 Derby Road, NG7 1NF, Nottingham", "ta": true, "far": false, "web": "https://www.alchemillarestaurant.uk", "drive": ""}, {"id": "n57", "cat": "splurge", "name": "Restaurant Sat Bains", "addr": "Lenton Lane, NG7 2SA", "text": "Nottingham's two-Michelin-star restaurant with rooms, curiously sited by the river under a flyover. One of the UK's great tasting menus; stay over and skip the drive home.", "tip": "Opens fewer days than it used to; book well ahead", "lat": 52.9353, "lon": -1.169, "price": 4, "walk": 39, "img": "img/n57.svg", "q": "Restaurant Sat Bains, Lenton Lane, NG7 2SA, Nottingham", "ta": true, "far": true, "web": "https://www.restaurantsatbains.com", "drive": ""}, {"id": "n58", "cat": "splurge", "name": "Hart's Kitchen", "addr": "Standard Hill, Park Row, NG1 6GN", "text": "A long-running, grown-up brasserie by the Castle, in Hart's Hotel. Reliable, polished modern British cooking.", "tip": "Lovely for Sunday lunch", "lat": 52.95147, "lon": -1.15662, "price": 3, "walk": 8, "img": "img/n58.svg", "q": "Hart's Kitchen, Standard Hill, Park Row, NG1 6GN, Nottingham", "ta": true, "far": false, "web": "https://www.hartsnottingham.co.uk", "drive": ""}, {"id": "n59", "cat": "pubs", "name": "Ye Olde Trip to Jerusalem", "addr": "1 Brewhouse Yard, NG1 6AD", "text": "Painted with '1189 AD', it claims to be England's oldest inn. The back rooms are caves cut straight into the sandstone under the Castle. Find the cursed model galleon in its glass case.", "tip": "Weekday afternoon for a cave room", "lat": 52.949362, "lon": -1.15267, "price": 1, "walk": 8, "img": "img/n59.svg", "q": "Ye Olde Trip to Jerusalem, 1 Brewhouse Yard, NG1 6AD, Nottingham", "ta": true, "far": false, "web": "https://www.triptojerusalem.com", "drive": ""}, {"id": "n60", "cat": "pubs", "name": "The Bell Inn", "addr": "18 Angel Row, NG1 6HL", "text": "A timber-framed pub right on the Market Square with medieval cellars and caves carved into the rock beneath. Live jazz some nights.", "tip": "Ask about cellar tours", "lat": 52.953387, "lon": -1.152056, "price": 1, "walk": 3, "img": "img/n60.svg", "q": "The Bell Inn, 18 Angel Row, NG1 6HL, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n61", "cat": "pubs", "name": "Hand & Heart", "addr": "65 Derby Road, NG1 5BA", "text": "An ordinary-looking frontage, but the back room is a cave carved into the sandstone cliff. Good real ales and food; quieter than the Trip.", "tip": "Sit in the cave room", "lat": 52.955402, "lon": -1.160238, "price": 1, "walk": 12, "img": "img/n61.svg", "q": "Hand & Heart, 65 Derby Road, NG1 5BA, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n62", "cat": "pubs", "name": "Kean's Head", "addr": "46 St Mary's Gate, NG1 1QA", "text": "A small, friendly corner pub opposite St Mary's church in the Lace Market. Castle Rock ales and decent food.", "tip": "Stop between galleries", "lat": 52.95131, "lon": -1.144043, "price": 1, "walk": 7, "img": "img/n62.svg", "q": "Kean's Head, 46 St Mary's Gate, NG1 1QA, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n63", "cat": "pubs", "name": "The Herbert Kilpin", "addr": "4 Bridlesmith Gate, NG1 2GR", "text": "Named after the Nottingham lace worker who founded AC Milan. Cosy, small, well-kept ales and good pies.", "tip": "Trivia to drop on your friends", "lat": 52.952, "lon": -1.1474, "price": 1, "walk": 3, "img": "img/n63.svg", "q": "The Herbert Kilpin, 4 Bridlesmith Gate, NG1 2GR, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n64", "cat": "pubs", "name": "The Organ Grinder", "addr": "21 Alfreton Road, Canning Circus, NG7 3JE", "text": "Blue Monkey brewery's pub at Canning Circus. Unpretentious, excellent beer and the famous pork pie and cheese plates.", "tip": "Pair with the Borlase Warren opposite", "lat": 52.956382, "lon": -1.16292, "price": 1, "walk": 15, "img": "img/n64.svg", "q": "The Organ Grinder, 21 Alfreton Road, Canning Circus, NG7 3JE, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n65", "cat": "pubs", "name": "Sir John Borlase Warren", "addr": "1 Ilkeston Road, Canning Circus, NG7 3GD", "text": "A rambling old pub of small rooms at the top of Derby Road, with a sun-trap beer garden.", "tip": "Last stop before strolling back down", "lat": 52.955768, "lon": -1.162267, "price": 1, "walk": 14, "img": "img/n65.svg", "q": "Sir John Borlase Warren, 1 Ilkeston Road, Canning Circus, NG7 3GD, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n66", "cat": "pubs", "name": "The Lincolnshire Poacher", "addr": "161 Mansfield Road, NG1 3FR", "text": "A pilgrimage pub for beer people, a 15-minute walk up Mansfield Road. Long tap list, whisky shelf, no nonsense.", "tip": "Mansfield Road has more good pubs for a crawl", "lat": 52.962165, "lon": -1.151416, "price": 1, "walk": 16, "img": "img/n66.svg", "q": "The Lincolnshire Poacher, 161 Mansfield Road, NG1 3FR, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n67", "cat": "pubs", "name": "Fox & Grapes", "addr": "21 Southwell Road, Sneinton, NG1 1DL", "text": "A Castle Rock pub on the edge of Sneinton Market, handy for galleries, studios and Bustler.", "tip": "Pair with Surface Gallery", "lat": 52.95367, "lon": -1.13771, "price": 1, "walk": 13, "img": "img/n67.svg", "q": "Fox & Grapes, 21 Southwell Road, Sneinton, NG1 1DL, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n68", "cat": "pubs", "name": "The Vat & Fiddle", "addr": "12–14 Queen's Bridge Road, NG2 1NB", "text": "Castle Rock brewery's own tap, next to the brewery and a few minutes from the station. Fresh ales and a proper local atmosphere.", "tip": "Last pint before the train", "lat": 52.9457, "lon": -1.14833, "price": 1, "walk": 14, "img": "img/n68.svg", "q": "The Vat & Fiddle, 12–14 Queen's Bridge Road, NG2 1NB, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n69", "cat": "pubs", "name": "The Angel Microbrewery", "addr": "7 Stoney Street, Lace Market, NG1 1LG", "text": "A historic Lace Market pub with its own microbrewery, gigs upstairs and a slightly chaotic, friendly vibe.", "tip": "Check the gig listings", "lat": 52.95339, "lon": -1.143392, "price": 1, "walk": 7, "img": "img/n69.svg", "q": "The Angel Microbrewery, 7 Stoney Street, Lace Market, NG1 1LG, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n70", "cat": "bars", "name": "The Hockley Arts Club", "addr": "20A Carlton Street, Hockley, NG1 1NN", "text": "A grand cocktail bar in a Grade II-listed building, dressed with art and music memorabilia. One of the city's showier nights out.", "tip": "Wed–Sun · lively late at weekends", "lat": 52.95331, "lon": -1.14433, "price": 3, "walk": 6, "img": "img/n70.svg", "q": "The Hockley Arts Club, 20A Carlton Street, Hockley, NG1 1NN, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n71", "cat": "bars", "name": "Junkyard", "addr": "12 Bridlesmith Walk, NG1 2HR", "text": "A small, dark, serious craft beer bar with a rotating tap list and good bar food.", "tip": "Ask the staff for a recommendation", "lat": 52.952503, "lon": -1.146155, "price": 2, "walk": 4, "img": "img/n71.svg", "q": "Junkyard, 12 Bridlesmith Walk, NG1 2HR, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n72", "cat": "bars", "name": "The Canal House", "addr": "48–52 Canal Street, NG1 7EH", "text": "An arm of the Nottingham Canal runs right through the middle of the bar, with a footbridge over it and a canalside terrace.", "tip": "Sit by the water inside", "lat": 52.94827, "lon": -1.14856, "price": 2, "walk": 9, "img": "img/n72.svg", "q": "The Canal House, 48–52 Canal Street, NG1 7EH, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n73", "cat": "bars", "name": "Broadway Cinema bar", "addr": "14–18 Broad Street, NG1 3AL", "text": "The independent cinema's café-bar, open to everyone. Full of film people and Hockley regulars.", "tip": "Pair with a film", "lat": 52.954306, "lon": -1.143663, "price": 1, "walk": 7, "img": "img/n73.svg", "q": "Broadway Cinema bar, 14–18 Broad Street, NG1 3AL, Nottingham", "ta": true, "far": false, "web": "https://www.broadway.org.uk", "drive": ""}, {"id": "n74", "cat": "bars", "name": "The Bodega", "addr": "23 Pelham Street, NG1 2ED", "text": "A pub downstairs and a small gig venue upstairs, where plenty of bands played early in their careers. A Hockley staple for a pint and a gig.", "tip": "Check the gig calendar", "lat": 52.953751, "lon": -1.145948, "price": 1, "walk": 4, "img": "img/n74.svg", "q": "The Bodega, 23 Pelham Street, NG1 2ED, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n75", "cat": "gear", "name": "Wex Photo Video", "addr": "103–107 Carrington Street, NG1 7FE", "text": "A big camera shop near the station with a proper used counter: second-hand lenses, bodies, flashes and accessories, all with a 12-month warranty. Stock changes daily and isn't all online, so it's worth a browse in person. They'll also buy or part-exchange your old kit.", "tip": "Used stock is first come, first served", "lat": 52.947804, "lon": -1.147325, "price": 0, "walk": 10, "img": "img/n75.svg", "q": "Wex Photo Video, 103–107 Carrington Street, NG1 7FE, Nottingham", "ta": true, "far": false, "web": "https://www.wexphotovideo.com/about-us/store-finder/nottingham/", "drive": ""}, {"id": "n76", "cat": "gear", "name": "Abbey Road Music (formerly PMT)", "addr": "Huntingdon Street, NG1", "text": "The city's big guitar, bass, drum and keyboard store. It had a large second-hand guitar wall under its former PMT name, and late in 2025 it changed hands to become Abbey Road Music.", "tip": "Name changed recently; check what's on the used wall", "lat": 52.9575, "lon": -1.1455, "price": 0, "walk": 9, "img": "img/n76.svg", "q": "Abbey Road Music (formerly PMT), Huntingdon Street, NG1, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n77", "cat": "gear", "name": "Drum & Guitar", "addr": "Cranbrook House, Cranbrook Street, NG1 1ES", "text": "Calls itself the largest independent music store in the East Midlands. Especially strong on drums, cymbals and percussion, with guitars and amps too, and staff who know their stuff.", "tip": "Ask about part-exchange and any used stock", "lat": 52.954089, "lon": -1.141337, "price": 0, "walk": 9, "img": "img/n77.svg", "q": "Drum & Guitar, Cranbrook House, Cranbrook Street, NG1 1ES, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n78", "cat": "gear", "name": "Nottingham City Guitars", "addr": "Lace Market, NG1", "text": "A luthier's workshop building hand-made electric guitars, with some finished shop stock for sale. Guitars start from around £1,500. A treat for a serious player.", "tip": "Open by appointment only; contact them first", "lat": 52.9523, "lon": -1.144, "price": 0, "walk": 7, "img": "img/n78.svg", "q": "Nottingham City Guitars, Lace Market, NG1, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n79", "cat": "gear", "name": "CeX, Victoria Centre", "addr": "Unit 310, Upper Mall, Victoria Centre, NG1 3QN", "text": "The buy-sell-exchange chain for second-hand phones, laptops, tablets, cameras, consoles and games, everything graded with a warranty. Handy for a cheap spare phone or a retro console.", "tip": "A second branch is on Exchange Walk", "lat": 52.9563, "lon": -1.1477, "price": 0, "walk": 6, "img": "img/n79.svg", "q": "CeX, Victoria Centre, Unit 310, Upper Mall, Victoria Centre, NG1 3QN, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n80", "cat": "gear", "name": "CeX, Exchange Walk", "addr": "2 Exchange Walk, NG1 2NX", "text": "The smaller central CeX, just off the Old Market Square, for second-hand tech, games and phones.", "tip": "Compare stock with the Victoria Centre branch", "lat": 52.952971, "lon": -1.148972, "price": 0, "walk": 1, "img": "img/n80.svg", "q": "CeX, Exchange Walk, 2 Exchange Walk, NG1 2NX, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n81", "cat": "food", "name": "The Cheese Shop", "addr": "4 Flying Horse Walk, NG1 2HN", "text": "Run by brothers Rob and Webb Freckingham for more than 15 years: a counter of British and continental cheeses, charcuterie, chutneys and crackers, plus the only café in Flying Horse Walk. A past World Cheese Awards placer.", "tip": "Ask for Colston Bassett or Cropwell Bishop Stilton, both made in Notts", "lat": 52.95281, "lon": -1.148486, "price": 0, "walk": 2, "img": "img/n81.svg", "q": "The Cheese Shop, 4 Flying Horse Walk, NG1 2HN, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n82", "cat": "food", "name": "Oriental Mart", "addr": "1A Goldsmith Street, NG1 5JS", "text": "Nottingham's best-known East Asian supermarket, with more than 3,000 Chinese, Japanese, Korean, Thai and Vietnamese products: fresh, frozen and dried. Its Umai street-food café serves bao, ramen and Hong Kong snacks.", "tip": "Good for snacks you won't find anywhere else", "lat": 52.955294, "lon": -1.152352, "price": 0, "walk": 5, "img": "img/n82.svg", "q": "Oriental Mart, 1A Goldsmith Street, NG1 5JS, Nottingham", "ta": true, "far": false, "web": "https://www.orientalmart.co.uk", "drive": ""}, {"id": "n83", "cat": "food", "name": "Asiana Hypermarket", "addr": "Woodborough Road, NG3", "text": "A huge Oriental supermarket on the edge of the centre, stocking foods from China, Hong Kong, Korea, Thailand, Japan, Vietnam and the Philippines, with big fresh and frozen sections.", "tip": "Easiest by car; it's uphill from Victoria Centre", "lat": 52.962281, "lon": -1.14675, "price": 0, "walk": 17, "img": "img/n83.svg", "q": "Asiana Hypermarket, Woodborough Road, NG3, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n84", "cat": "food", "name": "Radford Road world food trail", "addr": "Radford Road, Hyson Green, NG7", "text": "Half a mile of international grocers and bakeries where a dozen languages are spoken: South Asian and Middle Eastern spices at Medina Continental (79–83 Radford Road), exotic fruit and veg at Green Oranges, Polish bakes at Olawa Bakery and Eastern European goods at the Tani Shop. Wiloks nearby does African and Caribbean foods.", "tip": "Tram to Hyson Green Market; pair with New Art Exchange", "lat": 52.964717, "lon": -1.170356, "price": 0, "walk": 31, "img": "img/n84.svg", "q": "Radford Road world food trail, Radford Road, Hyson Green, NG7, Nottingham", "ta": false, "far": true, "web": "", "drive": ""}, {"id": "n85", "cat": "fun", "name": "Cave Escape", "addr": "63 Mansfield Road, NG1 3FN", "text": "Escape rooms built into a real sandstone cave system under Mansfield Road, which could only be in Nottingham. Three rooms for up to 18 players at once.", "tip": "Book ahead, especially at weekends", "lat": 52.959891, "lon": -1.15004, "price": 0, "walk": 12, "img": "img/n85.svg", "q": "Cave Escape, 63 Mansfield Road, NG1 3FN, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n86", "cat": "fun", "name": "Escapologic", "addr": "2 Stanford Street, NG1 7AQ", "text": "The city's biggest escape-room venue, with a range of themed rooms including 18+ horror games in the autumn.", "tip": "20% off a second room booked on the day · check hours", "lat": 52.950988, "lon": -1.149794, "price": 0, "walk": 4, "img": "img/n86.svg", "q": "Escapologic, 2 Stanford Street, NG1 7AQ, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n87", "cat": "fun", "name": "Break Escape", "addr": "9a Market Street & 107 Upper Parliament Street, NG1", "text": "A family-friendly escape-room company with two city-centre sites and a Robin Hood-themed room, plus Christmas rooms in December.", "tip": "Cheaper tickets for children", "lat": 52.954093, "lon": -1.151414, "price": 0, "walk": 2, "img": "img/n87.svg", "q": "Break Escape, 9a Market Street & 107 Upper Parliament Street, NG1, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n88", "cat": "fun", "name": "The Original Nottingham Ghost Walk", "addr": "Starts at Ye Olde Trip to Jerusalem, NG1 6AD", "text": "A costumed storyteller leads you round the Castle Quarter after dark, telling the city's ghost stories over about half a mile. Runs on Saturday evenings from January to the first Saturday in December.", "tip": "Saturdays 7pm · about £9 · just turn up", "lat": 52.949362, "lon": -1.15267, "price": 0, "walk": 8, "img": "img/n88.svg", "q": "The Original Nottingham Ghost Walk, Starts at Ye Olde Trip to Jerusalem, NG1 6AD, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n89", "cat": "fun", "name": "Ludorati Café", "addr": "Maid Marian Way, NG1", "text": "A board-game café with over 750 games, from old favourites to new ones, plus coffee, food and staff who'll teach you the rules. Great on a rainy afternoon.", "tip": "Book a table at weekends", "lat": 52.952, "lon": -1.153, "price": 0, "walk": 4, "img": "img/n89.svg", "q": "Ludorati Café, Maid Marian Way, NG1, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n90", "cat": "fun", "name": "The Dice Cup", "addr": "70 Mansfield Road, NG1 3GY", "text": "Nottingham's first board-game café and a proper games shop: dice, board games, tabletop miniatures and comics, with vegan-friendly food.", "tip": "Browse the shop even if you're not staying to play", "lat": 52.959179, "lon": -1.14918, "price": 0, "walk": 11, "img": "img/n90.svg", "q": "The Dice Cup, 70 Mansfield Road, NG1 3GY, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n91", "cat": "music", "name": "Rock City", "addr": "8 Talbot Street, NG1 5GG", "text": "A legendary independent rock venue since 1980, holding about 2,000 people. Just about every big guitar band of the last 40 years has played here, and its club nights are a Nottingham rite of passage.", "tip": "Check listings and book early for touring bands", "lat": 52.956062, "lon": -1.154025, "price": 0, "walk": 7, "img": "img/n91.svg", "q": "Rock City, 8 Talbot Street, NG1 5GG, Nottingham", "ta": true, "far": false, "web": "https://www.rock-city.co.uk", "drive": ""}, {"id": "n92", "cat": "music", "name": "Rescue Rooms", "addr": "Masonic Place, off Goldsmith Street, NG1 5JT", "text": "Rock City's 480-capacity little sibling next door, where you catch bands on the way up. It has a bar and kitchen, so it works for a drink even without a gig.", "tip": "Tickets often around £15–25", "lat": 52.95608, "lon": -1.153468, "price": 0, "walk": 6, "img": "img/n92.svg", "q": "Rescue Rooms, Masonic Place, off Goldsmith Street, NG1 5JT, Nottingham", "ta": true, "far": false, "web": "https://www.rescuerooms.com", "drive": ""}, {"id": "n93", "cat": "music", "name": "Metronome & the Glee Club", "addr": "Huntingdon Street, NG1 1AP", "text": "Nottingham Trent University's music and arts venue, now home to the Glee Club's comedy nights and Just the Tonic, plus gigs and club nights.", "tip": "Comedy weekends sell out; book ahead", "lat": 52.955916, "lon": -1.142529, "price": 0, "walk": 9, "img": "img/n93.svg", "q": "Metronome & the Glee Club, Huntingdon Street, NG1 1AP, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n94", "cat": "music", "name": "Nottingham Playhouse", "addr": "Wellington Circus, NG1 5AF", "text": "The city's producing theatre, with drama, its famous panto and touring work. Outside stands Anish Kapoor's Sky Mirror, a huge polished steel dish reflecting the sky, which is worth a look even if you're not seeing a show.", "tip": "The Sky Mirror is free to see any time", "lat": 52.953968, "lon": -1.156158, "price": 0, "walk": 7, "img": "img/n94.svg", "q": "Nottingham Playhouse, Wellington Circus, NG1 5AF, Nottingham", "ta": true, "far": false, "web": "https://www.nottinghamplayhouse.co.uk", "drive": ""}, {"id": "n95", "cat": "pubs", "name": "Ye Olde Salutation Inn", "addr": "Hounds Gate, NG1 7AA", "text": "A 13th-century-founded pub with caves beneath it, and a long-standing rock and live-music haunt. A third contender in the 'oldest pub in Nottingham' argument.", "tip": "Ask about seeing the caves", "lat": 52.951109, "lon": -1.151672, "price": 1, "walk": 4, "img": "img/n95.svg", "q": "Ye Olde Salutation Inn, Hounds Gate, NG1 7AA, Nottingham", "ta": true, "far": false, "web": "", "drive": ""}, {"id": "n96", "cat": "parks", "name": "Victoria Embankment", "addr": "Victoria Embankment, NG2", "text": "A broad tree-lined promenade along the River Trent, with memorial gardens, rowing clubs and views of Trent Bridge, the cricket ground and the City Ground. Flat and easy, and best on a sunny afternoon.", "tip": "Tram to Meadows Embankment", "lat": 52.9342, "lon": -1.138, "price": 0, "walk": 37, "img": "img/n96.svg", "q": "Victoria Embankment, Victoria Embankment, NG2, Nottingham", "ta": true, "far": true, "web": "", "drive": ""}, {"id": "n97", "cat": "parks", "name": "Nottingham Canal towpath", "addr": "Castle Wharf, Canal Street, NG1 7EH", "text": "Join the canal by the Canal House and walk west past old warehouses, narrowboats and Castle Marina. It's flat all the way, and you can carry on for an hour or more towards Beeston.", "tip": "Start or finish with a drink at the Canal House", "lat": 52.948137, "lon": -1.15026, "price": 0, "walk": 9, "img": "img/n97.svg", "q": "Nottingham Canal towpath, Castle Wharf, Canal Street, NG1 7EH, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n98", "cat": "parks", "name": "Highfields Park", "addr": "University Boulevard, NG7 2PS", "text": "A lakeside Victorian park beside the University of Nottingham, with a boating lake, a waterfall, a café and Lakeside Arts. Pair it with a walk up through the campus to the Trent Building.", "tip": "Tram to University of Nottingham", "lat": 52.936076, "lon": -1.193538, "price": 0, "walk": 57, "img": "img/n98.svg", "q": "Highfields Park, University Boulevard, NG7 2PS, Nottingham", "ta": true, "far": true, "web": "", "drive": ""}, {"id": "n99", "cat": "parks", "name": "The Forest Recreation Ground", "addr": "Mansfield Road, NG7", "text": "A huge open green on the hill north of the centre, home to Goose Fair every October and a tram Park & Ride. Big skies and views back over the city.", "tip": "The Forest tram stop is right there", "lat": 52.965334, "lon": -1.16093, "price": 0, "walk": 25, "img": "img/n99.svg", "q": "The Forest Recreation Ground, Mansfield Road, NG7, Nottingham", "ta": false, "far": false, "web": "", "drive": ""}, {"id": "n100", "cat": "parks", "name": "Colwick Country Park", "addr": "Mile End Road, Colwick, NG4 2DW", "text": "Lakes, woods and riverside paths on the east side of the city, with a marina and plenty of birdlife. Easy circular walks.", "tip": "About 10 minutes' drive; paid parking", "lat": 52.948382, "lon": -1.095981, "price": 0, "walk": 59, "img": "img/n100.svg", "q": "Colwick Country Park, Mile End Road, Colwick, NG4 2DW, Nottingham", "ta": true, "far": true, "web": "", "drive": ""}, {"id": "n101", "cat": "parks", "name": "Attenborough Nature Reserve", "addr": "Barton Lane, Attenborough, NG9 6DY", "text": "Flooded gravel pits turned into a wildlife haven beside the Trent, opened by Sir David Attenborough. A floating nature centre and café, kingfishers, herons and easy level paths.", "tip": "Train to Attenborough station, or 20 minutes by car", "lat": 52.899645, "lon": -1.235677, "price": 0, "walk": 135, "img": "img/n101.svg", "q": "Attenborough Nature Reserve, Barton Lane, Attenborough, NG9 6DY, Nottingham", "ta": true, "far": true, "web": "", "drive": ""}, {"id": "n102", "cat": "trips", "name": "Sherwood Forest & the Major Oak", "addr": "Edwinstowe, NG21", "text": "The heart of the old royal forest, with ancient oaks and woodland trails around the Major Oak, a giant tree held up by props and thought to be 800–1,000 years old. The visitor centre is in Edwinstowe, where legend says Robin Hood married Marian.", "tip": "Go early on weekends; Robin Hood Festival in August", "lat": 53.2048, "lon": -1.0724, "price": 0, "walk": 462, "img": "img/n102.svg", "q": "Sherwood Forest & the Major Oak, Edwinstowe, NG21, Nottingham", "ta": true, "far": true, "web": "", "drive": "40 min"}, {"id": "n103", "cat": "trips", "name": "Newstead Abbey", "addr": "Ravenshead, NG15 8NA", "text": "Lord Byron's ancestral home: the soaring west front of a medieval priory ruin attached to a country house, set in lakes, gardens and parkland with peacocks.", "tip": "Gardens daily · house weekends & school holidays 11–4", "lat": 53.078407, "lon": -1.192436, "price": 0, "walk": 231, "img": "img/n103.svg", "q": "Newstead Abbey, Ravenshead, NG15 8NA, Nottingham", "ta": true, "far": true, "web": "https://newsteadabbey.org.uk", "drive": "25 min"}, {"id": "n104", "cat": "trips", "name": "Southwell", "addr": "Southwell, NG25", "text": "A small Georgian minster town. The Norman Minster's chapter house has the famous 'Leaves of Southwell' stone carvings, and the National Trust Workhouse shows Victorian poor-relief. There are good independent shops and tearooms, and the Bramley apple started here.", "tip": "Pair the Minster and Workhouse with lunch in town", "lat": 53.076847, "lon": -0.954138, "price": 0, "walk": 308, "img": "img/n104.svg", "q": "Southwell, Southwell, NG25, Nottingham", "ta": true, "far": true, "web": "", "drive": "35 min"}, {"id": "n105", "cat": "trips", "name": "Creswell Crags", "addr": "Crags Road, Welbeck, S80 3LH", "text": "A limestone gorge of caves holding the UK's only known Ice Age cave art, plus hundreds of 'witches' marks' scratched to ward off evil. Guided cave tours, a lakeside walk and a visitor centre.", "tip": "Cave tours are guided; no under-5s on tours", "lat": 53.262042, "lon": -1.199179, "price": 0, "walk": 560, "img": "img/n105.svg", "q": "Creswell Crags, Crags Road, Welbeck, S80 3LH, Nottingham", "ta": true, "far": true, "web": "", "drive": "45 min"}, {"id": "n106", "cat": "trips", "name": "Clumber Park", "addr": "Worksop, S80 3BX", "text": "National Trust parkland with a big serpentine lake, a Gothic chapel, one of the longest double avenues of lime trees in Europe and a beautiful walled kitchen garden. Bikes to hire.", "tip": "Great for a long walk or a bike ride", "lat": 53.267873, "lon": -1.059039, "price": 0, "walk": 577, "img": "img/n106.svg", "q": "Clumber Park, Worksop, S80 3BX, Nottingham", "ta": true, "far": true, "web": "", "drive": "40 min"}, {"id": "n107", "cat": "trips", "name": "Hardwick Hall", "addr": "Doe Lea, Chesterfield, S44 5QJ", "text": "Bess of Hardwick's dazzling Elizabethan house, famous as 'more glass than wall', with huge tapestries and her initials on the rooftop. The ruined Old Hall stands next door.", "tip": "Just off M1 junction 29", "lat": 53.167998, "lon": -1.308801, "price": 0, "walk": 425, "img": "img/n107.svg", "q": "Hardwick Hall, Doe Lea, Chesterfield, S44 5QJ, Nottingham", "ta": true, "far": true, "web": "", "drive": "35 min"}, {"id": "n108", "cat": "trips", "name": "Ruddington", "addr": "Ruddington, NG11", "text": "A village with the Framework Knitters Museum (working Victorian knitting frames in original workshops), the Great Central Railway heritage steam and diesel line, and Debbie Bryan's second shop.", "tip": "Check the railway's running days", "lat": 52.891121, "lon": -1.151772, "price": 0, "walk": 112, "img": "img/n108.svg", "q": "Ruddington, Ruddington, NG11, Nottingham", "ta": true, "far": true, "web": "", "drive": "15 min"}, {"id": "n109", "cat": "trips", "name": "Colston Bassett Dairy", "addr": "Harby Lane, Colston Bassett, NG12", "text": "One of only a handful of dairies allowed to make Stilton, still making it by hand. Its small shop sells Stilton and Shropshire Blue straight from the source, in Vale of Belvoir countryside.", "tip": "Shop hours are short: weekdays & Saturday mornings", "lat": 52.891597, "lon": -0.956947, "price": 0, "walk": 238, "img": "img/n109.svg", "q": "Colston Bassett Dairy, Harby Lane, Colston Bassett, NG12, Nottingham", "ta": true, "far": true, "web": "", "drive": "25 min"}, {"id": "n110", "cat": "trips", "name": "Belvoir Castle", "addr": "Grantham, NG32 1PE", "text": "The Duke of Rutland's romantic hilltop castle overlooking the Vale of Belvoir, with lavish state rooms and landscaped gardens. Pair it with the Colston Bassett dairy shop on the way.", "tip": "Opening is seasonal; check dates before you go", "lat": 52.894692, "lon": -0.782689, "price": 0, "walk": 414, "img": "img/n110.svg", "q": "Belvoir Castle, Grantham, NG32 1PE, Nottingham", "ta": true, "far": true, "web": "", "drive": "40 min"}], "base": {"name": "Old Market Square", "addr": "Council House, Old Market Square, NG1 2DT", "lat": 52.95327, "lon": -1.14975}};
